"""Independent reasoning exercises, separate from each lesson's worked example."""
CHECKPOINTS = {
 'hello': ('Without running this different snippet, what appears?', 'print("Ready")\nprint("Go")', [('print','Two lines: Ready, then Go'), ('input','One line: Ready Go'), ('comment','Two lines including the quote characters')], 'print', 'Each print() writes its own line. Quotes describe strings and are not part of the displayed text.'),
 'variables': ('What value is printed after these assignments?', 'original = 4\ncopy = original\noriginal = 9\nprint(copy)', [('5','4'), ('2','9'), ('text','13')], '5', 'copy received the integer 4. Reassigning original to 9 does not reassign copy.'),
 'input': ('The user enters 4. What does this different program print?', 'quantity = input()\nprint(quantity + "2")', [('str','42'), ('int','6'), ('bool','It raises ValueError')], 'str', 'input() returns the string "4". Adding the string "2" joins the text into "42"; it does not add numbers.'),
 'calculator': ('Which exact value is displayed, including decimal places?', 'total = 18\npeople = 4\nprint(f"{total / people:.2f}")', [('tip','4.50'), ('ten','4.5'), ('divide','4.00')], 'tip', '18 divided by 4 is 4.5, and :.2f formats it with two decimal places: 4.50.'),
 'decisions': ('Which branch runs when the number is exactly 10?', 'affected = 10\nif affected > 10:\n    print("Escalate")\nelse:\n    print("Standard")', [('eq','Standard'), ('assign','Escalate'), ('different','Both messages')], 'eq', '10 > 10 is False because > excludes equality. Python runs only the else branch and prints Standard.'),
 'loops': ('Trace the loop. What is the final total?', 'total = 0\nfor number in range(2, 5):\n    total = total + number\nprint(total)', [('123','9'), ('1234','14'), ('0123','5')], '123', 'range(2, 5) visits 2, 3 and 4. Adding them gives 9; the stop value 5 is excluded.'),
 'lists': ('After appending another item, what does this index select?', 'items = ["pen", "book"]\nitems.append("cable")\nprint(items[1])', [('zero','book'), ('one','pen'), ('length','cable')], 'zero', 'The list is now pen, book, cable. Index 1 still refers to its second item, book.'),
 'functions': ('Follow the returned value into the next calculation. What is printed?', 'def add_one(number):\n    return number + 1\n\nresult = add_one(3)\nprint(result * 2)', [('return','8'), ('print','4'), ('input','6')], 'return', 'add_one(3) returns 4. The caller then multiplies that returned value by 2 and prints 8.'),
 'validation': ('The user enters 2.5. What happens in this program?', 'try:\n    quantity = int(input())\n    print(quantity)\nexcept ValueError:\n    print("Whole number required")', [('error','It prints Whole number required'), ('zero','It prints 2'), ('text','It prints 2.5')], 'error', 'int() cannot convert the decimal string "2.5" directly into an integer. ValueError is caught and the message is printed.'),
 'final-mission': ('This service name has spaces and uppercase letters. Which replacement makes the dictionary lookup work?', 'rates = {"basic": 10, "urgent": 20}\nservice = " BASIC "\n# Replace the next line\nservice = service.lower()\nprint(rates[service])', [('reuse','service = service.strip().lower()'), ('speed','service = service.upper()'), ('required','service = str(service)')], 'reuse', 'strip() removes the surrounding spaces and lower() changes BASIC to basic, matching the dictionary key.'),
}
